import{_ as e,o,c as d,ae as r}from"./chunks/framework.DQC_QtFV.js";const _=JSON.parse('{"title":"排障","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1793162416000}'),a={name:"guide/troubleshooting.md"};function c(l,t,s,i,n,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="排障" tabindex="-1">排障 <a class="header-anchor" href="#排障" aria-label="Permalink to &quot;排障&quot;">​</a></h1><table tabindex="0"><thead><tr><th>现象</th><th>含义与处理</th></tr></thead><tbody><tr><td><code>error: no QQ source: set exactly one of ...</code></td><td><code>QQ_DEB_URL</code> 和挂载的 deb 都没给，见 <a href="./first-start.html">首次启动</a></td></tr><tr><td><code>error: sha256 mismatch: expected ... got ...</code></td><td>这个 deb 不是固定版本，换一个文件</td></tr><tr><td><code>error: both QQ_DEB_URL and the mounted deb ... are set</code></td><td>去掉其中一个</td></tr><tr><td>实时画面一直停在二维码</td><td>这是正常的：扫码登录是手动的，由你完成</td></tr><tr><td><code>db.key = &quot;missing&quot;</code></td><td>密钥提取还没完成。日志在宿主机的 <code>./logs/keyx.log</code>（容器内 <code>/out/keyx.log</code>）。驱动程序会继续等，密钥就绪后状态自己变成 <code>&quot;ok&quot;</code></td></tr><tr><td><code>db.key = &quot;invalid&quot;</code></td><td>客户端换过密钥，或私有副本对不上。按面板 QQ 页上给的步骤重新提取</td></tr><tr><td>面板页面返回 502</td><td>driver 或 bot 还没起来，看 <code>docker compose logs qq bot</code></td></tr><tr><td>机器人一轮都不开始</td><td>先看 概览 的 待处理：至少一个管理员、允许列表里至少一个会话，两者齐备才开轮</td></tr><tr><td>一条消息都发不出去</td><td>Jev 不可达时出口审查失败关闭。去 <a href="./console/models.html">模型</a> 看它的状态、补 key</td></tr><tr><td>沙箱里装不了技能、连不上源</td><td>目标域名不在放行名单里。去 <a href="./console/safety.html">安全</a> 的 网络 看名单，删掉误拦的条目让它重新判定</td></tr><tr><td>改了人设没变化</td><td>人设在下一个窗口生效，或用页面上的 立即轮换</td></tr></tbody></table><h2 id="日志在哪" tabindex="-1">日志在哪 <a class="header-anchor" href="#日志在哪" aria-label="Permalink to &quot;日志在哪&quot;">​</a></h2><ul><li>面板的 <a href="./console/logs.html">日志</a> 页：驱动、机器人和面板自己的事件，可筛选、实时。</li><li>宿主机的 <code>./logs/</code>：<code>qq</code> 容器自己的诊断日志，<strong>可能包含聊天内容</strong>，不要分享。</li></ul><h2 id="还不行" tabindex="-1">还不行 <a class="header-anchor" href="#还不行" aria-label="Permalink to &quot;还不行&quot;">​</a></h2><p>带上这些信息再提问：镜像 tag（<code>PERSONAL_BOT_TAG</code> 或 <code>latest</code>）、 <code>docker compose ps</code> 的输出、<code>./logs/qq.log</code> 和 <code>./logs/keyx.log</code> 的尾部 （聊天内容先删掉），以及面板 <a href="./console/">概览</a> 的截图（mock 数据也可以）。</p>',6)])])}const m=e(a,[["render",c]]);export{_ as __pageData,m as default};
